const unsigned char lead = static_cast<unsigned char>(input[0]);
// input[0]에 접근하기 전에 input.empty()를 검사한다.
// 뒤 바이트에 접근하기 전에 input.size() >= length를 검사한다.

enum class Status { end, scalar, invalid };

struct Result {
    char32_t codepoint = 0;
    std::size_t bytes = 0;
    Status status = Status::end;
};

inline Result decode_first(std::string_view input) noexcept {
    if (input.empty()) {
        return Result{};
    }

    const unsigned char lead = static_cast<unsigned char>(input[0]);

    if (lead <= 0x7F) {
        // 00..7F, including an embedded U+0000, is a 1-byte scalar.
        return {static_cast<char32_t>(lead), 1, Status::scalar};
    }
    if (lead >= 0xC2 && lead <= 0xDF) {
        // 2-byte sequence; C0/C1 would encode below U+0080.
        if (input.size() < 2) {
            return {0xFFFD, 1, Status::invalid};
        }
        return detail::assemble(input, 2, 0x1Fu, 0x80);
    }
    if (lead >= 0xE0 && lead <= 0xEF) {
        // 3-byte sequence; overlong and surrogate results are rejected below.
        if (input.size() < 3) {
            return {0xFFFD, 1, Status::invalid};
        }
        return detail::assemble(input, 3, 0x0Fu, 0x800);
    }
    if (lead >= 0xF0 && lead <= 0xF4) {
        // 4-byte sequence; F4 results above U+10FFFF are rejected below.
        if (input.size() < 4) {
            return {0xFFFD, 1, Status::invalid};
        }
        return detail::assemble(input, 4, 0x07u, 0x10000);
    }
    // 80..BF is a stray continuation; C0/C1 and F5..FF are never valid leads.
    return {0xFFFD, 1, Status::invalid};
}

inline Result assemble(std::string_view input, std::size_t length,
                       std::uint32_t lead_mask, char32_t minimum) noexcept {
    std::uint32_t value = static_cast<std::uint32_t>(
        static_cast<unsigned char>(input[0]) & lead_mask);
    for (std::size_t i = 1; i < length; ++i) {
        const unsigned char byte = static_cast<unsigned char>(input[i]);
        if (!is_continuation(byte)) {
            return {0xFFFD, 1, Status::invalid};
        }
        value = (value << 6) | (static_cast<std::uint32_t>(byte) & 0x3Fu);
    }
    const char32_t code = static_cast<char32_t>(value);
    if (code < minimum || code > kMaxCodepoint ||
        (code >= kSurrogateLow && code <= kSurrogateHigh)) {
        return {0xFFFD, 1, Status::invalid};
    }
    return {code, length, Status::scalar};
}

static void inspect(std::string_view input){
    std::size_t offset=0;
    while(!input.empty()){
        const auto item=study_utf8::decode_first(input);
        std::printf("byte %zu: U+%04lX, consumed=%zu, %s\n",offset,
          static_cast<unsigned long>(item.codepoint),item.bytes,
          item.status==study_utf8::Status::scalar?"scalar":"invalid");
        input.remove_prefix(item.bytes);offset+=item.bytes;
    }
}

static uint32_t utf8_next(const char** text)
{
    std::size_t available = 0;
    while (available < 4 && (*text)[available] != '\0') ++available;
    const auto result = utf8::decode_first(std::string_view(*text, available));
    *text += result.bytes;
    return static_cast<uint32_t>(result.codepoint);
}

struct Label {
    std::array<char32_t,16> scalars{};
    std::size_t count=0;
    std::size_t invalid_bytes=0;
};
inline std::optional<Label> decode(std::string_view input) noexcept {
    Label label;
    while(!input.empty()){
        if(label.count==label.scalars.size())return std::nullopt;
        const auto item=study_utf8::decode_first(input);
        label.scalars[label.count++]=item.codepoint;
        if(item.status==study_utf8::Status::invalid)++label.invalid_bytes;
        input.remove_prefix(item.bytes);
    }
    return label;
}

inline constexpr std::string_view menu_text=u8"대기실";
inline constexpr std::string_view play_text=u8"플레이";
struct Labels { Label menu,play; };
inline std::optional<Labels> make() noexcept {
    const auto menu=decode(menu_text),play=decode(play_text);
    if(!menu || !play)return std::nullopt;
    return Labels{*menu,*play};
}

static void report_label(const study_labels::Label& label) {
    std::printf("UI label: %zu scalars, %zu invalid bytes:",label.count,label.invalid_bytes);
    for(std::size_t i=0;i<label.count;++i)
        std::printf(" U+%04lX",static_cast<unsigned long>(label.scalars[i]));
    std::putchar('\n');
}

